const HOUSE_RULES={"it":{"intro":"Qualche attenzione per un soggiorno piacevole e nel rispetto di tutti.","rows":[["Rispetto della quiete","Mantieni un tono di voce moderato, soprattutto al mattino e alla sera. Tieni basso anche il volume del televisore, per rispettare il riposo degli altri ospiti."],["Animali","Gli animali non sono ammessi all’interno della struttura."],["Rientro dalla spiaggia","Per la sicurezza e la pulizia degli ambienti, è vietato entrare bagnati nelle aree interne. Asciugati prima di rientrare."],["Divieto di fumo","È vietato fumare in tutta la struttura, anche nelle aree esterne."]],"more":"Apri la sezione","end":"Per qualsiasi esigenza, contatta Cinzia e Alberto."},"en":{"intro":"A few simple guidelines for a pleasant stay and consideration for everyone.","rows":[["Peace and quiet","Keep your voice moderate, especially in the morning and evening. Keep the television volume low to respect other guests’ rest."],["Pets","Pets are not allowed inside the property."],["Returning from the beach","For safety and cleanliness, do not enter indoor areas while wet. Dry yourself before coming inside."],["No smoking","Smoking is prohibited throughout the property, including outdoor areas."]],"more":"Open section","end":"For anything you need, contact Cinzia and Alberto."},"de":{"intro":"Ein paar Hinweise für einen angenehmen Aufenthalt und ein rücksichtsvolles Miteinander.","rows":[["Ruhe","Sprich bitte in gemäßigter Lautstärke, besonders morgens und abends. Halte auch die Lautstärke des Fernsehers niedrig, damit andere Gäste sich ausruhen können."],["Haustiere","Haustiere sind im Haus nicht erlaubt."],["Rückkehr vom Strand","Betritt die Innenräume aus Sicherheits- und Sauberkeitsgründen nicht nass. Trockne dich vor dem Eintreten ab."],["Rauchverbot","Das Rauchen ist auf dem gesamten Gelände verboten, auch in den Außenbereichen."]],"more":"Bereich öffnen","end":"Bei Fragen oder Wünschen wende dich an Cinzia und Alberto."},"fr":{"intro":"Quelques attentions pour un séjour agréable dans le respect de chacun.","rows":[["Respect du calme","Parle à voix modérée, surtout le matin et le soir. Garde également le volume de la télévision bas pour respecter le repos des autres hôtes."],["Animaux","Les animaux ne sont pas admis à l’intérieur de l’établissement."],["Retour de la plage","Pour la sécurité et la propreté, il est interdit d’entrer mouillé dans les espaces intérieurs. Sèche-toi avant de rentrer."],["Interdiction de fumer","Il est interdit de fumer dans tout l’établissement, y compris dans les espaces extérieurs."]],"more":"Ouvrir la rubrique","end":"Pour toute demande, contacte Cinzia et Alberto."},"es":{"intro":"Unas pautas para una estancia agradable y respetuosa con todos.","rows":[["Respeto del descanso","Habla en un tono moderado, especialmente por la mañana y por la noche. Mantén bajo el volumen del televisor para respetar el descanso de los demás."],["Animales","No se admiten animales en el interior del establecimiento."],["Vuelta de la playa","Por seguridad y limpieza, está prohibido entrar mojado en las zonas interiores. Sécate antes de entrar."],["Prohibido fumar","Está prohibido fumar en todo el establecimiento, incluidas las zonas exteriores."]],"more":"Abrir sección","end":"Para cualquier necesidad, contacta con Cinzia y Alberto."},"nl":{"intro":"Een paar afspraken voor een prettig verblijf met respect voor iedereen.","rows":[["Rust","Praat op gedempte toon, vooral ’s ochtends en ’s avonds. Zet ook de televisie zacht om de rust van andere gasten te respecteren."],["Huisdieren","Huisdieren zijn niet toegestaan binnen de accommodatie."],["Terug van het strand","Voor de veiligheid en netheid mag je de binnenruimtes niet nat betreden. Droog je af voordat je naar binnen gaat."],["Rookverbod","Roken is overal in de accommodatie verboden, ook in de buitenruimtes."]],"more":"Onderdeel openen","end":"Neem voor vragen of wensen contact op met Cinzia en Alberto."},"pl":{"intro":"Kilka zasad zapewniających przyjemny pobyt i wzajemny szacunek.","rows":[["Cisza i spokój","Rozmawiaj umiarkowanym głosem, szczególnie rano i wieczorem. Utrzymuj niski poziom głośności telewizora, aby nie zakłócać odpoczynku innych gości."],["Zwierzęta","Zwierzęta nie są dozwolone wewnątrz obiektu."],["Powrót z plaży","Ze względu na bezpieczeństwo i czystość nie wolno wchodzić do wnętrz, będąc mokrym. Osusz się przed wejściem."],["Zakaz palenia","Palenie jest zabronione w całym obiekcie, również na zewnątrz."]],"more":"Otwórz sekcję","end":"W razie potrzeby skontaktuj się z Cinzią i Albertem."}};
