const BEACH_PARTNER_TEXT={"it":{"sea":"Il mare è proprio davanti a noi.","title":"Convenzione Lungomare 70 · Marzocca Beach Tennis","benefit":"Gli ospiti di Lungomare 70 possono utilizzare gratuitamente il campo, le racchette e le palline. Su richiesta, sono disponibili anche le prime indicazioni per imparare a giocare.","contact":"Per organizzarti, chiedi a Cinzia e Alberto: ti metteranno in contatto con Roberto."},"en":{"sea":"The sea is just in front of us.","title":"Lungomare 70 guest offer · Marzocca Beach Tennis","benefit":"Lungomare 70 guests can use the court, rackets and balls free of charge. On request, beginners can also receive some basic tips to start playing.","contact":"Ask Cinzia and Alberto to arrange this: they will put you in touch with Roberto."},"de":{"sea":"Das Meer liegt direkt vor dem Haus.","title":"Lungomare 70 Partnerangebot · Marzocca Beach Tennis","benefit":"Gäste von Lungomare 70 können den Platz, die Schläger und die Bälle kostenlos nutzen. Auf Wunsch gibt es auch erste Tipps für den Einstieg ins Spiel.","contact":"Frage Cinzia und Alberto zur Organisation: Sie stellen den Kontakt zu Roberto her."},"fr":{"sea":"La mer est juste devant nous.","title":"Offre Lungomare 70 · Marzocca Beach Tennis","benefit":"Les hôtes de Lungomare 70 peuvent utiliser gratuitement le terrain, les raquettes et les balles. Sur demande, quelques conseils de base sont aussi proposés pour commencer à jouer.","contact":"Pour t’organiser, demande à Cinzia et Alberto : ils te mettront en contact avec Roberto."},"es":{"sea":"El mar está justo enfrente.","title":"Convenio Lungomare 70 · Marzocca Beach Tennis","benefit":"Los huéspedes de Lungomare 70 pueden utilizar gratuitamente la pista, las raquetas y las pelotas. Si lo solicitas, también puedes recibir unas primeras indicaciones para empezar a jugar.","contact":"Para organizarte, pregunta a Cinzia y Alberto: te pondrán en contacto con Roberto."},"nl":{"sea":"De zee ligt direct voor ons.","title":"Lungomare 70 gastenvoordeel · Marzocca Beach Tennis","benefit":"Gasten van Lungomare 70 kunnen gratis gebruikmaken van de baan, rackets en ballen. Op verzoek zijn er ook enkele basistips om te leren spelen.","contact":"Vraag Cinzia en Alberto om dit te regelen: zij brengen je in contact met Roberto."},"pl":{"sea":"Morze znajduje się tuż przed obiektem.","title":"Oferta Lungomare 70 · Marzocca Beach Tennis","benefit":"Goście Lungomare 70 mogą bezpłatnie korzystać z boiska, rakiet i piłek. Na życzenie dostępne są również podstawowe wskazówki, jak zacząć grać.","contact":"Aby to zorganizować, zapytaj Cinzię i Alberta: skontaktują Cię z Robertem."}};
